import './Hero.css';
import Image from '../assets/image.png';
const Hero = () => {
    return (
        <div className="hero">
            <h1 className="title">Welcome to our Store</h1>
            <div className='hero-image'>
                <img src="../assets/image.jpg"/>
            </div>
        </div>
    )
}

export default Hero;
